// NORMALISER ONLY. This node no longer decides anything.
//
// D5: this runs before any sheet is loaded, so it must use only immutable data
// from the Gmail event. It used to also MATCH, by regexing the first [MAT-...]
// out of subject+body, and that matching was the defect: the tag travels in
// every letter we send, so a quoted or forwarded tag could attach a reply to
// the wrong legal matter. Resolution now happens in Build Reply Context, after
// the register is loaded.
//
// Deliberately no matter_id, no action_id and no matched flag here.
//
// NO CLOCK. received_at is an ingress fingerprint input, so it must be either the
// provider's own timestamp or empty. It previously fell back to
// new Date().toISOString(), which made the fingerprint of an undated message
// different on every delivery: an ordinary retry would then have been reported as
// an IDEMPOTENCY_CONFLICT needing human review. An absent timestamp is absent.

// The trigger runs with simple:false, so from/to may arrive as a string, an
// array, or a parsed object. String() on an object yields "[object Object]",
// which would poison the sender check and refuse every reply.
function addrOf(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(addrOf).filter(Boolean).join(', ');
  if (typeof v === 'object') {
    if (v.address) return String(v.address);
    if (v.email) return String(v.email);
    if (v.value) return addrOf(v.value);
    if (v.text) return String(v.text);
    if (v.name && v.addr) return String(v.addr);
  }
  return '';
}

// A deterministic id for the one branch that has no provider message id to work with.
// Reply Matched? sends an event with no id here, and this used to be stamped
// 'EVT-' + a timestamp + a random number, so replaying one undated Gmail item wrote a
// new Events row every time and the tab counted arrivals instead of recording the one
// decision "an inbound arrived that could not be identified". There is no message id to
// key on, so the key is a hash of the stable ingress fields that DO exist. Two genuinely
// different unidentifiable messages still get two rows; the same one replayed gets one.
function fnv1aHex(str) {
  let h = 0x811c9dc5;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + (h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24)) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}
function canon(s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); }

const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const headers = j.headers || {};
  const subject = String(j.subject || headers.subject || '');
  const body = String(j.text || j.textPlain || j.snippet || '').slice(0, 20000);
  const provider_message_id = String(j.id || '');
  const from_address = addrOf(j.from) || addrOf(headers.from);
  const received_at = String(j.date || headers.date || '');
  out.push({ json: {
    has_event: !!provider_message_id,
    provider_message_id,
    thread_id: String(j.threadId || ''),
    from_address,
    from_parse_ok: !!from_address && from_address.indexOf('[object') === -1,
    to_address: addrOf(j.to) || addrOf(headers.to),
    subject,
    body_text: body,
    received_at,
    has_provider_timestamp: !!received_at,
    // Used only by Log Unmatched Reply. Never a substitute for the resolver's own
    // ingress fingerprint, which is computed after the register is loaded.
    unmatched_event_id: 'EVT-UNMATCHED-' + fnv1aHex(
      'thread=' + String(j.threadId || '') + ' from=' + from_address
      + ' subject=' + canon(subject) + ' body=' + canon(body)
      + ' ts=' + received_at),
  }});
}
return out;

// ---------------------------------------------------------------------------
// Ingress-only replay resolution. Pure: no I/O, no clock, no randomness.
//
// The conflict detector runs on the RAW INBOUND MESSAGE, before classification.
// It never compares summary, classification, or a regenerated communication_id:
// those are downstream products, and comparing them would make every ordinary
// retry a false conflict. (An earlier harness did exactly that, which is how the
// mistake was found.)
//
// Stable ingress fields only: provider_message_id, thread_id, sender address,
// subject, raw body, provider timestamp. They are combined into one
// ingress_fingerprint, stored in Communications.ingress_fingerprint. The digest is
// stored, never the raw body: the body stays in Gmail and Drive.
//
// communication_id is DETERMINISTIC ('COM-' + provider_message_id), so it is
// created once on first delivery and the identical value is returned on every
// replay. A stored value always wins over a recomputed one.
//
// Required behaviour:
//   same message id + same raw message  -> ALREADY_RECORDED, no classifier, no mutation
//   same message id + different raw     -> IDEMPOTENCY_CONFLICT, human review, no mutation
//   different message id                -> NEW_INBOUND, continue to classification
// ---------------------------------------------------------------------------
const REAL_OUTBOUND = ['OUTBOUND', 'OUTBOUND_PENDING'];
const up = s => String(s == null ? '' : s).toUpperCase();
const trim = s => String(s == null ? '' : s).trim();

function emailOf(s) {
  const raw = String(s == null ? '' : s);
  const m = raw.match(/<([^>]+)>/);
  return String(m ? m[1] : raw).trim().toLowerCase();
}

// FNV-1a. Detects change; it is not cryptographic and does not resist forgery.
// The register is not attacker-writable, so change detection is the requirement.
function fnv1a(str) {
  let h = 0x811c9dc5;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + (h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24)) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}
// Whitespace is normalised so a transport-level reflow is not read as a different
// message. Nothing else is normalised.
function canon(s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); }

function ingressFingerprint(e) {
  const parts = [
    'pmid=' + trim(e.provider_message_id),
    'thread=' + trim(e.thread_id),
    'from=' + emailOf(e.from),
    'subject=' + canon(e.subject),
    'body=' + canon(e.body),
    'ts=' + trim(e.received_at)
  ].join(' ');
  return 'ING-' + fnv1a(parts) + '-' + String(canon(e.body).length);
}

function splitQuoted(body) {
  const text = String(body == null ? '' : body);
  const markers = [
    /^[ \t]*On\s[\s\S]{0,200}?\swrote:[ \t]*$/m,
    /^[ \t]*-{2,}\s*Original Message\s*-{2,}[ \t]*$/im,
    /^[ \t]*_{5,}[ \t]*$/m,
    /^[ \t]*From:[ \t]*\S[\s\S]{0,400}?^[ \t]*(Sent|Date):[ \t]*\S/im,
    /^[ \t]*>{1,}/m
  ];
  let cut = -1;
  for (const re of markers) {
    const m = re.exec(text);
    if (m && (cut === -1 || m.index < cut)) cut = m.index;
  }
  if (cut === -1) return { unquoted: text, quoted: '' };
  return { unquoted: text.slice(0, cut), quoted: text.slice(cut) };
}

function tagsIn(s) {
  const found = [];
  const re = /\[(MAT-[A-Za-z0-9-]+)\]/gi;
  let m;
  while ((m = re.exec(String(s == null ? '' : s))) !== null) {
    const id = m[1].toUpperCase();
    if (found.indexOf(id) === -1) found.push(id);
  }
  return found;
}

function resolveReply(event, register) {
  const ev = event || {};
  const reg = register || {};
  const matters = (reg.matters || []).filter(m => m && m.matter_id);
  const comms = (reg.comms || []).filter(c => c && c.matter_id);

  const messageId = trim(ev.provider_message_id);
  const threadId = trim(ev.thread_id);
  const sender = emailOf(ev.from);
  const subject = String(ev.subject == null ? '' : ev.subject);
  const parts = splitQuoted(ev.body);
  const fingerprint = ingressFingerprint(ev);
  const commId = messageId ? 'COM-' + messageId : '';

  const authoritativeTags = tagsIn(subject + '\n' + parts.unquoted);
  const quotedOnlyTags = tagsIn(parts.quoted).filter(t => authoritativeTags.indexOf(t) === -1);

  const onRegister = id => matters.some(m => up(m.matter_id) === up(id));
  const realOut = comms.filter(c => REAL_OUTBOUND.includes(up(c.direction)));
  const acceptedIn = comms.filter(c => up(c.direction) === 'INBOUND');
  const partiesOf = id => new Set(
    realOut.filter(c => up(c.matter_id) === up(id))
      .map(c => emailOf(c.recipient)).filter(Boolean)
  );

  const base = {
    decision: 'BLOCKED', basis: 'NO_AUTHORITATIVE_BASIS', matter_id: '',
    reason: '', sender_address: sender, thread_id: threadId,
    provider_message_id: messageId,
    communication_id: commId,
    ingress_fingerprint: fingerprint,
    stored_fingerprint: '',
    requires_human_review: false,
    authoritative_tags: authoritativeTags, quoted_only_tags: quotedOnlyTags,
    audit_event: 'INBOUND_REPLY_NO_BASIS',
    event_id: messageId ? 'EVT-BLOCKED-' + messageId + '-NO_AUTHORITATIVE_BASIS' : '',
    event_type: 'INBOUND_REPLY_NO_BASIS', severity: 'WARNING',
    write_log_inbound: false, write_append_action: false, write_touch_matter: false
  };
  const out = o => Object.assign({}, base, o);

  // ---- Replay detection, on ingress fields only ---------------------------
  if (messageId) {
    const prior = acceptedIn.find(c => trim(c.provider_message_id) === messageId);
    if (prior) {
      const storedFp = trim(prior.ingress_fingerprint);
      const storedComm = trim(prior.communication_id) || commId;
      if (!storedFp) {
        // Row predates fingerprinting. Identity cannot be established, so fail
        // closed: still no mutation, but ask for a human look.
        return out({
          decision: 'IDEMPOTENCY_CONFLICT', basis: 'FINGERPRINT_NOT_RECORDED',
          matter_id: up(prior.matter_id), communication_id: storedComm,
          requires_human_review: true,
          reason: 'Message ' + messageId + ' is already recorded on ' + up(prior.matter_id)
            + ', but that row carries no ingress fingerprint, so it cannot be confirmed identical. Nothing was changed.',
          audit_event: '<REDACTED_FILEID_2>',
          event_id: 'EVT-REPLAY-CONFLICT-' + messageId,
          event_type: '<REDACTED_FILEID_2>', severity: 'WARNING'
        });
      }
      if (storedFp === fingerprint) {
        return out({
          decision: 'ALREADY_RECORDED', basis: 'ALREADY_RECORDED',
          matter_id: up(prior.matter_id), communication_id: storedComm,
          stored_fingerprint: storedFp,
          reason: 'Message ' + messageId + ' is already recorded on ' + up(prior.matter_id)
            + ' and the raw message is identical. Ignored.',
          audit_event: 'INBOUND_REPLAY_IGNORED',
          event_id: 'EVT-REPLAY-' + messageId,
          event_type: 'INBOUND_REPLAY_IGNORED', severity: 'INFO'
        });
      }
      return out({
        decision: 'IDEMPOTENCY_CONFLICT', basis: 'IDEMPOTENCY_CONFLICT',
        matter_id: up(prior.matter_id), communication_id: storedComm,
        stored_fingerprint: storedFp, requires_human_review: true,
        reason: 'Message ' + messageId + ' is already recorded on ' + up(prior.matter_id)
          + ' but the raw message differs (stored ' + storedFp + ', now ' + fingerprint
          + '). Nothing was changed. Human review required.',
        audit_event: '<REDACTED_FILEID_2>',
        event_id: 'EVT-REPLAY-CONFLICT-' + messageId,
        event_type: '<REDACTED_FILEID_2>', severity: 'WARNING'
      });
    }
  }

  // ---- Matter resolution: thread first ------------------------------------
  const threadRows = threadId
    ? realOut.concat(acceptedIn).filter(c => trim(c.thread_id) === threadId)
    : [];
  const threadMatters = Array.from(new Set(threadRows.map(c => up(c.matter_id))));

  let matterId = '';
  let basis = '';
  const blocked = (b, reason, evType) => out({
    decision: 'BLOCKED', basis: b, matter_id: matterId, reason: reason,
    audit_event: evType, event_type: evType, severity: 'WARNING',
    event_id: messageId ? 'EVT-BLOCKED-' + messageId + '-' + b : ''
  });

  if (threadMatters.length === 1) {
    matterId = threadMatters[0];
    basis = 'THREAD';
    if (authoritativeTags.length && authoritativeTags.indexOf(matterId) === -1) {
      return blocked('THREAD_MISMATCH',
        'The thread belongs to ' + matterId + ' but the message tags ' + authoritativeTags.join(', ') + '.',
        '<REDACTED_FILEID_7>');
    }
  } else if (threadMatters.length > 1) {
    return blocked('THREAD_AMBIGUOUS',
      'Thread ' + threadId + ' appears on more than one matter.', '<REDACTED_FILEID_6>');
  } else {
    if (!authoritativeTags.length) {
      return blocked('NO_AUTHORITATIVE_BASIS',
        quotedOnlyTags.length
          ? 'No usable thread. The only matter ids appear in quoted history: ' + quotedOnlyTags.join(', ') + '.'
          : 'No usable thread and no matter tag in the subject or the unquoted body.',
        'INBOUND_REPLY_NO_BASIS');
    }
    if (authoritativeTags.length > 1) {
      return blocked('TAG_AMBIGUOUS',
        'No usable thread and the message tags several matters: ' + authoritativeTags.join(', ') + '.',
        'INBOUND_REPLY_TAG_AMBIGUOUS');
    }
    matterId = authoritativeTags[0];
    if (!onRegister(matterId)) {
      return blocked('NOT_ON_REGISTER', 'Matter ' + matterId + ' is not on the register.',
        '<REDACTED_FILEID_3>');
    }
    const senderMatters = Array.from(new Set(
      realOut.filter(c => emailOf(c.recipient) === sender).map(c => up(c.matter_id))
    ));
    if (senderMatters.length > 1 && tagsIn(subject).indexOf(matterId) === -1) {
      return blocked('NO_AUTHORITATIVE_BASIS',
        'No usable thread. ' + sender + ' is a party to ' + senderMatters.length
          + ' matters, and the tag is not in the subject, so the matter cannot be established.',
        'INBOUND_REPLY_NO_BASIS');
    }
    basis = 'TAG';
  }

  if (!onRegister(matterId)) {
    return blocked('NOT_ON_REGISTER', 'Matter ' + matterId + ' is not on the register.',
      '<REDACTED_FILEID_3>');
  }
  const parties = partiesOf(matterId);
  if (!sender) return blocked('NO_SENDER', 'No readable sender address.', 'INBOUND_REPLY_NO_SENDER');
  if (!parties.size) return blocked('NO_CORRESPONDENCE',
    'Nothing has been sent to anyone on ' + matterId + ', so there is no correspondence to reply to.',
    '<REDACTED_FILEID_4>');
  if (!parties.has(sender)) return blocked('SENDER_NOT_A_PARTY',
    sender + ' is not an address this matter has written to.', '<REDACTED_FILEID_5>');

  return out({
    decision: 'ACCEPT', basis: basis, matter_id: matterId, reason: 'First delivery of ' + messageId + '. Recorded.',
    audit_event: 'NEW_INBOUND',
    event_id: 'EVT-INBOUND-' + messageId,
    event_type: 'NEW_INBOUND', severity: 'INFO',
    write_log_inbound: true, write_append_action: true, write_touch_matter: true
  });
}

// ----------------------------- adapter ------------------------------------
// $input is Load Comms (Reply), so every register slice is read by node name.
const r = $('Match Reply to Matter').first().json;
const matters = $('Load Matters (Reply)').all().map(i => i.json).filter(x => x && x.matter_id);
const actions = $('Load Actions (Reply)').all().map(i => i.json).filter(x => x && x.action_id);
const comms = $('Load Comms (Reply)').all().map(i => i.json).filter(x => x && x.matter_id);

const res = resolveReply({
  provider_message_id: r.provider_message_id,
  thread_id: r.thread_id,
  from: r.from_address,
  subject: r.subject,
  body: r.body_text,
  received_at: r.received_at
}, { matters: matters, comms: comms });

const matter = matters.filter(m => up(m.matter_id) === up(res.matter_id)).pop() || null;
const mine = actions.filter(a => up(a.matter_id) === up(res.matter_id));
const openAction = mine.filter(a => ['COMPLETED', 'SENT', 'FAILED'].indexOf(up(a.status)) === -1).pop() || null;
const nextSeq = String(mine.length + 1).padStart(3, '0');

return [{ json: Object.assign({}, r, res, {
  matched: res.decision === 'ACCEPT',
  sender_verified: res.decision === 'ACCEPT',
  unverified_kind: res.decision === 'ACCEPT' ? '' : res.basis,
  unverified_reason: res.reason,
  matter_title: matter ? String(matter.title || '') : '',
  playbook_id: matter ? String(matter.playbook_id || '') : '',
  jurisdiction: matter ? String(matter.jurisdiction || '') : '',
  matter_status: matter ? String(matter.status || '') : '',
  action_id: openAction ? String(openAction.action_id || '') : '',
  action_type: openAction ? String(openAction.action_type || '') : '',
  action_description: openAction ? String(openAction.description || '') : '',
  next_action_id: res.matter_id ? String(res.matter_id).replace('MAT-', 'ACT-') + '-' + nextSeq : ''
}) }];

const c = $('Build Reply Context').first().json;
let raw = $input.first().json;
if (raw && raw.output) raw = raw.output;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }

const allowed = ['ACKNOWLEDGEMENT','REQUEST_FOR_INFORMATION','DENIAL','OFFER','COUNTEROFFER',
  'SETTLEMENT_PROPOSAL','ACCEPTANCE','REJECTION','DEADLINE_NOTICE','NEW_EVIDENCE','ESCALATION','UNKNOWN'];

const ok = raw && typeof raw === 'object' && allowed.includes(raw.classification);
const cls = ok ? raw.classification : 'UNKNOWN';

// ---------------------------------------------------------------------------
// D3. A deadline the sender stated has to land in a column Date.parse can read,
// or it is invisible to the daily digest and to the follow-up detector. The raw
// wording is never discarded: it is what the owner must actually act on, and it
// is the only defensible record of what the other side said.
//
// Order matters. The numeric day/month/year branch runs BEFORE Date.parse,
// because Date.parse reads a bare 5/8/2026 as 8 May (US) while Western
// Australia means 5 August. Getting that backwards moves a legal deadline by
// nearly three months and records it as if it were certain.
// ---------------------------------------------------------------------------
const MONTHS = 'January|February|March|April|May|June|July|August|September|October|November|December';
function normaliseDeadline(input) {
  const rawText = String(input == null ? '' : input).trim();
  if (!rawText) return { iso: '', raw: '', parsed: false, ambiguous: false };

  // 1. Numeric d/m/y, day first.
  const au = rawText.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})\b/);
  if (au) {
    const dNum = Number(au[1]), mNum = Number(au[2]);
    if (mNum >= 1 && mNum <= 12 && dNum >= 1 && dNum <= 31) {
      const t = Date.parse(au[3] + '-' + String(mNum).padStart(2, '0') + '-' + String(dNum).padStart(2, '0') + 'T00:00:00Z');
      // Ambiguous only when both numbers could be a month, e.g. 5/8 vs 8/5.
      if (!Number.isNaN(t)) return { iso: new Date(t).toISOString(), raw: rawText, parsed: true, ambiguous: dNum <= 12 };
    }
  }

  // 2. A month name, e.g. "5pm AWST on 25 August 2026" or "COB 25 Aug 2026".
  const prose = rawText.match(new RegExp('(\\d{1,2})\\s+(' + MONTHS + '|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\\.?\\s+(\\d{4})', 'i'));
  if (prose) {
    const t = Date.parse(prose[1] + ' ' + prose[2] + ' ' + prose[3] + ' 00:00:00Z');
    if (!Number.isNaN(t)) return { iso: new Date(t).toISOString(), raw: rawText, parsed: true, ambiguous: false };
  }

  // 3. An ISO date, possibly embedded in a longer string.
  const iso = rawText.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    const t = Date.parse(iso[0] + 'T00:00:00Z');
    if (!Number.isNaN(t)) return { iso: new Date(t).toISOString(), raw: rawText, parsed: true, ambiguous: false };
  }

  // 4. Last resort: anything else Date.parse understands, e.g. "August 25, 2026".
  const t = Date.parse(rawText);
  if (!Number.isNaN(t)) return { iso: new Date(t).toISOString(), raw: rawText, parsed: true, ambiguous: false };

  // Relative wording such as "within 21 days" is deliberately NOT resolved here.
  // Doing so would require knowing the start date and the counting rule, which is
  // exactly the kind of limitation calculation this system must never invent.
  return { iso: '', raw: rawText, parsed: false, ambiguous: false };
}

const statedFlag = ok && raw.deadline_is_stated === true;
const dl = normaliseDeadline(ok ? raw.deadline_date : '');

let deadlineBasis = '';
if (dl.raw) {
  if (statedFlag) deadlineBasis = dl.parsed ? 'STATED_BY_SENDER' : 'STATED_BY_SENDER_UNPARSED';
  else deadlineBasis = 'UNVERIFIED_ESTIMATE';
}
if (dl.parsed && dl.ambiguous) deadlineBasis = deadlineBasis + '_AMBIGUOUS_DMY';
const deadlineUnparsed = !!dl.raw && !dl.parsed;

// An offer or settlement proposal is never actioned automatically. It becomes a decision for the owner.
const decisionClasses = ['OFFER','COUNTEROFFER','SETTLEMENT_PROPOSAL','ACCEPTANCE','REJECTION'];
const needsOwnerDecision = decisionClasses.includes(cls);

const createAction = ok && (raw.response_needed === true || needsOwnerDecision);
const nextType = needsOwnerDecision ? 'OWNER_DECISION'
  : String((ok && raw.suggested_next_action_type) || 'REVIEW_DOCUMENT').toUpperCase();

// Fail-safe. The previous version whitelisted the types that DO need approval and
// defaulted everything else to FALSE, so OWNER_DECISION and REVIEW_AND_DECIDE --
// which is what a settlement offer produces -- were written requires_approval FALSE.
// Now only an explicitly harmless, purely internal action skips approval.
const NO_APPROVAL_NEEDED = ['REVIEW_DOCUMENT','COLLECT_INFORMATION','FILE_NOTE'];
const requiresApproval = NO_APPROVAL_NEEDED.includes(nextType) ? 'FALSE' : 'TRUE';

let nextDescription = needsOwnerDecision
  ? 'An offer or proposal arrived. It requires your decision. I accepted nothing. I rejected nothing.'
  : String((ok && raw.suggested_next_action) || 'Review the reply and decide the next step.');
if (deadlineUnparsed) {
  nextDescription = 'UNPARSED DEADLINE, CONFIRM IT YOURSELF: the sender wrote "' + dl.raw
    + '", which I could not turn into a calendar date. This action has no due date. It will NOT appear in the daily overdue list. '
    + nextDescription;
} else if (dl.parsed && dl.ambiguous) {
  nextDescription = 'AMBIGUOUS DATE: the sender wrote "' + dl.raw + '". I read it day first, as '
    + dl.iso.slice(0, 10) + '. If they meant month first, correct it. ' + nextDescription;
}

return [{ json: {
  ...c,
  json_valid: !!ok,
  classification: cls,
  summary: ok ? String(raw.summary || '').slice(0, 700) : 'The classifier returned nothing usable. Read the email yourself.',
  response_needed: ok ? raw.response_needed === true : true,
  requests: ok && Array.isArray(raw.requests) ? raw.requests.map(String) : [],
  deadline_date: dl.raw,
  due_at_iso: dl.iso,
  deadline_parsed: dl.parsed,
  deadline_unparsed: deadlineUnparsed,
  deadline_ambiguous: dl.ambiguous,
  deadline_basis: deadlineBasis,
  notes: ok ? String(raw.notes || '') : 'CLASSIFIER_FAILED',
  needs_owner_decision: needsOwnerDecision,
  create_action: createAction,
  next_action_type: nextType,
  next_action_description: nextDescription.slice(0, 700),
  next_action_priority: (needsOwnerDecision || deadlineUnparsed || dl.ambiguous) ? 'HIGH' : 'MEDIUM',
  <REDACTED_FILEID_10>: requiresApproval,
  // communication_id is NOT regenerated here. Build Reply Context supplies a
  // deterministic 'COM-' + provider_message_id, and a stored value wins over a
  // recomputed one, so it is created once and identical on every replay. It
  // arrives via the ...c spread above. Regenerating it from the clock made the
  // Telegram notice report an id that did not exist in the Communications sheet.
}}];

const r = $('Validate Reply JSON').first().json;
const lines = [
  'Reply received',
  '',
  'Matter: ' + r.matter_id + '  ' + r.matter_title,
  'Action: ' + (r.action_id || 'not identified'),
  'From: ' + r.from_address,
  'Subject: ' + r.subject,
  'Classification: ' + r.classification,
  'Logged as: ' + r.communication_id,
  '',
  'Summary: ' + r.summary,
];
if (r.requests.length) lines.push('', 'They asked for:', ...r.requests.map(x => '- ' + x));
if (r.deadline_date) lines.push('', 'Date mentioned: ' + r.deadline_date + '  (' + r.deadline_basis + ')');
if (r.needs_owner_decision) {
  lines.push('', 'This is an offer or a proposal.',
    'I have not accepted or rejected anything, and I will not.',
    'Action ' + r.next_action_id + ' needs your decision.');
} else if (r.create_action) {
  lines.push('', 'Next action created: ' + r.next_action_id + '  ' + r.next_action_type);
}
if (!r.json_valid) lines.push('', 'The classifier failed on this email. Read it in Gmail before acting.');
lines.push('', 'Reply here to tell me what to do next.');
return [{ json: { reply: lines.join('\n').slice(0, 3900) } }];

// Deterministic. No model runs here, so no deadline can be invented.
//
// ============================================================================
// WHY THIS NODE COLLAPSES ROWS BEFORE IT COUNTS ANYTHING
//
// The 2026-08-22 report said "Open actions: 27" and then listed 13 rows. It put
// one action in both ACTIONS AWAITING APPROVAL and BLOCKED, and listed another
// twice under BLOCKED. None of that was a formatting fault.
//
// The Actions tab holds one row per WRITE, not one row per action. Until
// 2026-08-19T18:25Z, WF2's Append Actions used operation=append with NO matching
// column, so every re-plan wrote a fresh set of rows under the same positional
// action ids. Two later fixes closed that: upsert on idempotency_key, then
// per-plan-stamped ids. Everything written since is unique. The duplicates in the
// register are historical residue from before those fixes, not a live write fault.
// The old report filtered rows directly, so one action_id could still satisfy two
// section filters at once and be counted twice.
//
// Two dimensions were also being conflated. The Actions sheet has ONE status
// column, so BLOCKED and AWAITING_APPROVAL are mutually exclusive AS A STATUS.
// But "is an approval outstanding" lives in the Approvals tab and is a SEPARATE
// dimension: an action can be blocked on a dependency while an approval sits
// against it. This node now carries both on one record and prints them together,
// rather than emitting the same action as two operational rows.
//
// WHAT IT WILL NOT DO. Where duplicate rows disagree about what the action IS
// (different action_type under one action_id), that is an identity collision and
// no rule can resolve it. Those are reported as DATA_INTEGRITY_CONFLICT and kept
// out of the operational sections entirely. Guessing would be worse than saying
// nothing: the two rows are genuinely different pieces of work.
//
// Nothing here writes, decides, approves, or sends. Reporting only.
// ============================================================================

const matters   = $('Load Matters (Digest)').all().map(i => i.json).filter(r => r && r.matter_id);
const actionRows= $('Load Actions (Digest)').all().map(i => i.json).filter(r => r && r.action_id);
const approvals = $('Load Approvals (Digest)').all().map(i => i.json).filter(r => r && r.approval_id);
const evidence  = $('Load Evidence (Digest)').all().map(i => i.json).filter(r => r && r.evidence_id);
const events    = $('Load Events (Digest)').all().map(i => i.json).filter(r => r && r.event_id);
const drafts    = (() => { try { return $('Load Drafts (Digest)').all().map(i => i.json).filter(r => r && r.draft_id); }
                           catch (e) { return []; } })();
// Conflict notices. Read defensively: the register may not exist yet, and a digest
// must never fail because of a register it only reports on.
const notices   = (() => { try { return $('Load Conflict Notices (Digest)').all().map(i => i.json).filter(r => r && r.conflict_key); }
                           catch (e) { return []; } })();

const QUIET_DAYS = 14;
const MAX_ROWS_PER_SECTION = 12;   // sections are attention-only; overflow is stated, never silent
const CEILING = 3600;              // final message budget, measured before send
const now = new Date();
const today = now.toISOString().slice(0, 10);
const dayMs = 86400000;
const DONE = ['COMPLETED', 'SENT', 'FAILED', 'CANCELLED'];

const up = v => String(v === null || v === undefined ? '' : v).trim().toUpperCase();
function daysSince(v) { const t = Date.parse(String(v || '')); return Number.isNaN(t) ? null : Math.floor((now.getTime() - t) / dayMs); }
function dueIn(v)     { const t = Date.parse(String(v || '')); return Number.isNaN(t) ? null : Math.ceil((t - now.getTime()) / dayMs); }
function stamp(r)     { const t = Date.parse(String(r.updated_at || r.created_at || '')); return Number.isNaN(t) ? -1 : t; }

// ---- TEST / SYNTHETIC ISOLATION -------------------------------------------
// General predicate, not a list of ids.
//
// THE ASYMMETRY THAT SETS THE THRESHOLD. Mislabelling a test matter as live is
// untidy. Mislabelling a LIVE matter as test hides real legal work from the only
// daily report the owner reads. So this predicate only fires on markers that
// cannot plausibly occur in a genuine matter title.
//
// An earlier version of this node matched bare \bTEST\b, \bQA\b, \bSANDBOX\b and
// \bSYNTHETIC\b anywhere in the title. Checked against realistic titles, that
// wrongly excluded 'Employment contract - QA Engineer, Perth', 'Dispute over
// failed emissions test on purchased vehicle', 'Contract with 3 month test
// period' and 'Claim against Sandbox Pty Ltd'. Any of those would have vanished
// from the live figures without a trace. The markers below were checked against
// the same set: every real test matter is still caught, and none of those four is.
//
// facts.dry_run is deliberately NOT a signal. dry_run is a system-wide operating
// mode, currently true for everything, so treating it as a test marker would hide
// every live matter the moment it appeared in recorded facts.
function isTestMatter(m) {
  if (!m) return false;
  const id = up(m.matter_id);
  const title = up(m.title);
  if (/^<REDACTED_CASEREF_2>\b|^MAT-QA\b|^<REDACTED_CASEREF_1>\b/.test(id)) return true;
  if (/\bTEST[ _-]ONLY\b|\bDO NOT USE\b/.test(title)) return true;
  let facts = {}; try { facts = JSON.parse(m.facts_json || '{}'); } catch (e) {}
  for (const k of ['test_data_only', 'matter_flagged_test_only', 'is_test']) {
    if (up(facts[k]) === 'TRUE') return true;
  }
  let risks = []; try { risks = JSON.parse(m.risk_flags_json || '[]'); } catch (e) {}
  if (risks.some(r => /TEST[_ ]ONLY|SYNTHETIC|DO[_ ]NOT[_ ]USE/i.test(String(r)))) return true;
  return false;
}
const matterById = {};
matters.forEach(m => { matterById[m.matter_id] = m; });   // last row per id wins
const testMatterIds = {};
Object.keys(matterById).forEach(id => { if (isTestMatter(matterById[id])) testMatterIds[id] = true; });
const isTestId = id => !!testMatterIds[String(id)];
const matterTitle = id => String((matterById[id] || {}).title || '');

// ---- CANONICAL ACTION RECORDS ---------------------------------------------
// One record per distinct action_id. Duplicate rows are collapsed by latest
// updated_at, EXCEPT where they describe different work, which is unresolvable.
const rowsById = {};
actionRows.forEach(a => { (rowsById[a.action_id] = rowsById[a.action_id] || []).push(a); });

const canonical = [];        // one per action_id, conflict-free
const identityConflicts = [];// one per action_id whose rows disagree on what it is
const collapsed = [];        // duplicates resolved by recency, recorded for hygiene

Object.keys(rowsById).forEach(id => {
  const rows = rowsById[id];
  const types = Array.from(new Set(rows.map(r => up(r.action_type)).filter(Boolean)));
  const matterIds = Array.from(new Set(rows.map(r => String(r.matter_id)).filter(Boolean)));

  if (types.length > 1 || matterIds.length > 1) {
    identityConflicts.push({
      action_id: id,
      reason: types.length > 1 ? '<REDACTED_FILEID_8>' : '<REDACTED_FILEID_9>',
      candidates: rows.map(r => ({
        action_type: r.action_type, status: r.status, matter_id: r.matter_id,
        idempotency_key: r.idempotency_key, updated_at: r.updated_at,
      })),
    });
    return;                                  // fail closed: never guess which is current
  }

  const ordered = rows.slice().sort((a, b) => stamp(a) - stamp(b));
  const winner = ordered[ordered.length - 1];
  if (rows.length > 1) {
    collapsed.push({
      action_id: id, rows: rows.length,
      statuses: Array.from(new Set(rows.map(r => up(r.status)))),
      kept_status: up(winner.status), kept_updated_at: winner.updated_at,
    });
  }
  canonical.push(winner);
});

// ---- APPROVAL STATE, WITH SUPERSESSION DERIVED, NEVER WRITTEN --------------
// A PENDING row is only LIVE if its draft is the newest draft for that action.
// Approval Gate already refuses an older draft as STALE, so reporting those as
// actionable invites the owner to approve something the gate will reject.
// Nothing is written back: the Approvals tab keeps its full history untouched.
const latestDraftVersion = {};
drafts.forEach(d => {
  const v = parseInt(d.version || '0', 10) || 0;
  const k = String(d.action_id);
  if (!latestDraftVersion[k] || v > latestDraftVersion[k]) latestDraftVersion[k] = v;
});
const draftById = {};
drafts.forEach(d => { draftById[String(d.draft_id)] = d; });

function draftVersionOf(a) {
  const d = draftById[String(a.draft_id)];
  if (d) { const v = parseInt(d.version || '0', 10); return Number.isNaN(v) ? null : v; }
  const m = String(a.draft_id || '').match(/-v(\d+)$/);   // fall back to the id's own suffix
  return m ? parseInt(m[1], 10) : null;
}

const pendingRows = approvals.filter(a => up(a.status) === 'PENDING');
const liveApprovals = [];
const supersededUnrecorded = [];
const approvalStateUnknown = [];

pendingRows.forEach(a => {
  const actionId = String(a.action_id);
  const mine = draftVersionOf(a);
  const newest = latestDraftVersion[actionId];

  if (mine === null || newest === undefined) {
    // Cannot establish which draft this approval refers to. Fail closed:
    // neither live nor superseded, and it does not appear as actionable.
    approvalStateUnknown.push({ approval_id: a.approval_id, action_id: actionId,
      draft_id: a.draft_id, reason: mine === null ? 'DRAFT_VERSION_UNRESOLVABLE' : 'NO_DRAFT_ROW_FOR_ACTION' });
    return;
  }
  if (mine < newest) {
    supersededUnrecorded.push({ approval_id: a.approval_id, action_id: actionId, matter_id: a.matter_id,
      draft_id: a.draft_id, draft_version: mine, newest_version: newest });
    return;
  }
  liveApprovals.push(a);
});

// More than one live approval on a single action is itself a conflict.
const liveByAction = {};
liveApprovals.forEach(a => { (liveByAction[String(a.action_id)] = liveByAction[String(a.action_id)] || []).push(a); });
const multiLiveApproval = Object.keys(liveByAction).filter(k => liveByAction[k].length > 1)
  .map(k => ({ action_id: k, approval_ids: liveByAction[k].map(a => a.approval_id) }));

const liveApprovalByAction = {};
Object.keys(liveByAction).forEach(k => { if (liveByAction[k].length === 1) liveApprovalByAction[k] = liveByAction[k][0]; });

// ---- ONE RECORD, TWO DIMENSIONS -------------------------------------------
function decorate(a) {
  const apr = liveApprovalByAction[String(a.action_id)];
  const superseded = supersededUnrecorded.filter(s => s.action_id === String(a.action_id)).length;
  return {
    action_id: a.action_id,
    matter_id: a.matter_id,
    action_type: a.action_type,
    workflow_status: up(a.status),
    approval_state: apr ? 'APPROVAL_PENDING' : (superseded ? 'APPROVAL_SUPERSEDED' : 'NONE'),
    approval_id: apr ? apr.approval_id : '',
    draft_id: apr ? apr.draft_id : '',
    blocked_reason: a.blocked_reason || '',
    due_at: a.due_at || '',
    deadline_basis: a.deadline_basis || '',
    is_test: isTestId(a.matter_id),
  };
}
const records = canonical.map(decorate);
const openRecords = records.filter(r => DONE.indexOf(r.workflow_status) === -1);
const liveOpen = openRecords.filter(r => !r.is_test);
const testOpen = openRecords.filter(r => r.is_test);

// A single line carries both dimensions, so one action is never two rows.
function line(r) {
  const bits = [r.action_id, r.action_type, r.workflow_status];
  if (r.approval_state === 'APPROVAL_PENDING') bits.push('approval ' + r.approval_id + ' PENDING');
  else if (r.approval_state === 'APPROVAL_SUPERSEDED') bits.push('approval superseded, none live');
  if (r.workflow_status === 'BLOCKED' && r.blocked_reason) bits.push('(' + r.blocked_reason + ')');
  return bits.join('  ');
}

// ---- MATTERS ---------------------------------------------------------------
const openMatters = matters.filter(m => ['CLOSED', 'REJECTED'].indexOf(up(m.status)) === -1);
const liveMatters = openMatters.filter(m => !isTestMatter(m));
const testMatters = openMatters.filter(m => isTestMatter(m));
const needsInput = liveMatters.filter(m => up(m.status) === 'NEEDS_INFORMATION');

const missingEvidence = liveMatters.filter(m => {
  let req = []; try { req = JSON.parse(m.required_evidence_json || '[]'); } catch (e) {}
  const have = evidence.filter(e => String(e.matter_id) === String(m.matter_id)).length;
  return req.length > 0 && have === 0;
});
const quiet = liveMatters.filter(m => { const d = daysSince(m.last_activity_at || m.updated_at); return d !== null && d >= QUIET_DAYS; });

// ---- ATTENTION BUCKETS (live only) ----------------------------------------
const dated    = liveOpen.filter(r => String(r.due_at).trim());
const overdue  = dated.filter(r => { const d = dueIn(r.due_at); return d !== null && d < 0; });
const dueToday = dated.filter(r => dueIn(r.due_at) === 0);
const dueWeek  = dated.filter(r => { const d = dueIn(r.due_at); return d !== null && d > 0 && d <= 7; });
const awaiting = liveOpen.filter(r => r.approval_state === 'APPROVAL_PENDING');
const blocked  = liveOpen.filter(r => r.workflow_status === 'BLOCKED' && r.approval_state !== 'APPROVAL_PENDING');
const held     = liveOpen.filter(r => r.workflow_status === 'HELD');

const attentionIds = {};
[].concat(overdue, dueToday, dueWeek, awaiting, blocked, held).forEach(r => { attentionIds[r.action_id] = true; });
const attentionCount = Object.keys(attentionIds).length;
const notShown = liveOpen.length - attentionCount;

const failures = events.filter(e => { const d = daysSince(e.created_at); return up(e.severity) === 'ERROR' && d !== null && d <= 1; });
const security = events.filter(e => { const d = daysSince(e.created_at); return String(e.event_type || '').startsWith('UNAUTHORISED') && d !== null && d <= 1; });

function section(title, rows) {
  if (!rows.length) return null;
  const shown = rows.slice(0, MAX_ROWS_PER_SECTION);
  const body = title + ' (' + rows.length + ')\n' + shown.map(r => '  ' + r).join('\n');
  return rows.length > shown.length
    ? body + '\n  ... and ' + (rows.length - shown.length) + ' more not shown here'
    : body;
}

// ---- CONFLICT NOTICES ------------------------------------------------------
// A notice is only silent when it has been reported. PENDING, FAILED and EXHAUSTED
// all appear here, so an unresolved conflict cannot disappear just because the
// notification path failed or was never built.
const S2 = v => String(v === null || v === undefined ? '' : v).trim();
const NST = r => { const v = up(r.notification_status); return v || (S2(r.notified_at) ? 'SENT' : 'PENDING'); };
function noticeLine(r) {
  let ids = [];
  try { ids = JSON.parse(r.action_ids_json || '[]'); } catch (e) {}
  return S2(r.conflict_key) + '  ' + S2(r.matter_id)
    + '  ' + (ids.length ? ids.join(', ') : 'no action ids')
    + '  seen ' + (S2(r.occurrence_count) || '?') + 'x'
    + '  since ' + S2(r.first_seen_at).slice(0, 10);
}
const noticesPending   = notices.filter(r => NST(r) === 'PENDING');
const noticesFailed    = notices.filter(r => NST(r) === 'FAILED');
const noticesExhausted = notices.filter(r => NST(r) === 'EXHAUSTED');
// Two rows sharing a conflict_key is the register's own integrity failure.
const noticeKeyCounts = {};
notices.forEach(r => { const k = S2(r.conflict_key); noticeKeyCounts[k] = (noticeKeyCounts[k] || 0) + 1; });
const noticeDuplicates = Object.keys(noticeKeyCounts).filter(k => noticeKeyCounts[k] > 1);

const integrity = []
  .concat(noticeDuplicates.map(k => k + '  DUPLICATE_CONFLICT_KEY_ROWS  ' + noticeKeyCounts[k]
      + ' rows share this key. Suppression cannot be trusted until a human removes the extras.'))
  .concat(identityConflicts.map(c => c.action_id + '  ' + c.reason + '  candidates: '
      + c.candidates.map(x => (x.action_type || '?') + '/' + up(x.status)).join(' vs ')))
  .concat(multiLiveApproval.map(c => c.action_id + '  MULTIPLE_LIVE_APPROVALS  ' + c.approval_ids.join(', ')))
  .concat(approvalStateUnknown.map(a => a.approval_id + '  ' + a.reason + '  action ' + a.action_id));

// Each section carries a drop priority. Under budget pressure the HIGHEST number
// yields first. Priority 0 is undroppable: an integrity conflict and the test/live
// separation must never be the thing that falls off the end of a message.
const spec = [
  [0, 'DATA_INTEGRITY_CONFLICT - needs manual review, excluded from the counts below', integrity],
  [0, 'TEST AND QA MATTERS - not live work', testMatters.map(m =>
    m.matter_id + '  ' + up(m.status) + '  ' + (m.title || '').slice(0, 60))],
  [0, 'CONFLICT NOTICES NEVER REPORTED - notification abandoned, needs manual review',
    noticesExhausted.map(noticeLine)],
  [1, 'CONFLICT NOTICES AWAITING NOTIFICATION', noticesPending.map(noticeLine)],
  [1, 'CONFLICT NOTICES WHOSE NOTIFICATION FAILED - will be retried',
    noticesFailed.map(r => noticeLine(r) + '  attempts ' + (S2(r.notification_attempts) || '0')
      + (S2(r.last_notification_error) ? '  last error: ' + S2(r.last_notification_error).slice(0, 80) : ''))],
  [1, 'SECURITY EVENTS IN THE LAST 24 HOURS', security.map(e => e.event_type + ' at ' + e.created_at)],
  [1, 'NEEDS YOUR INFORMATION', needsInput.map(m => m.matter_id + '  ' + (m.title || ''))],
  [1, 'APPROVALS WAITING', liveApprovals.filter(a => !isTestId(a.matter_id)).map(a =>
    a.approval_id + '  ' + a.matter_id + '  draft ' + a.draft_id + '  raised ' + String(a.requested_at || '').slice(0, 16))],
  [1, 'ACTIONS AWAITING APPROVAL', awaiting.map(line)],
  [1, 'OVERDUE', overdue.map(r => line(r) + '  due ' + r.due_at + '  [' + (r.deadline_basis || 'NO_BASIS_RECORDED') + ']')],
  [1, 'SUPERSEDED APPROVALS STILL MARKED PENDING - not actionable, register not updated',
    supersededUnrecorded.map(s => s.approval_id + '  ' + s.action_id + '  draft v' + s.draft_version + ' superseded by v' + s.newest_version)],
  [2, 'DUE TODAY', dueToday.map(r => line(r) + '  [' + (r.deadline_basis || 'NO_BASIS_RECORDED') + ']')],
  [2, 'HELD AFTER REJECTION', held.map(r => r.action_id + '  ' + r.matter_id)],
  [2, 'FAILED RUNS IN THE LAST 24 HOURS', failures.map(e =>
    e.workflow + ' / ' + e.node + ': ' + String(e.message || '').slice(0, 120))],
  [3, 'DUE THIS WEEK', dueWeek.map(r => line(r) + '  due ' + r.due_at)],
  [3, 'BLOCKED', blocked.map(line)],
  [4, 'DUPLICATE ROWS COLLAPSED - most recent kept',
    collapsed.map(c => c.action_id + '  ' + c.rows + ' rows [' + c.statuses.join(', ') + '] kept ' + c.kept_status)],
  [4, 'MISSING EVIDENCE', missingEvidence.map(m => m.matter_id + '  ' + (m.title || ''))],
  [4, 'NO ACTIVITY FOR ' + QUIET_DAYS + '+ DAYS', quiet.map(m =>
    m.matter_id + '  last activity ' + String(m.last_activity_at || 'unknown').slice(0, 10))],
];
const built = spec.map(([p, title, rows], i) => ({ p, i, text: section(title, rows) })).filter(b => b.text);
const blocks = built.map(b => b.text);

// ---- RECONCILIATION HEADER -------------------------------------------------
// Every distinct action id is accounted for in exactly one bucket, and the
// buckets are printed even when zero, so nothing can appear to vanish between
// the register and the report. 'Open actions: 27' followed by 13 rows is the
// failure this replaces: it stated a number and then silently showed a subset.
//
// distinct ids = countable live open + identity conflicts + test-only + closed
// If that identity ever fails, RECONCILIATION MISMATCH is printed rather than
// quietly showing figures that do not add up.
const doneRecords = records.filter(r => DONE.indexOf(r.workflow_status) !== -1);
const distinctIds = Object.keys(rowsById).length;
const accounted = liveOpen.length + identityConflicts.length + testOpen.length + doneRecords.length;
const duplicateRows = actionRows.length - distinctIds;

const head = [
  'Daily case report  ' + today,
  'Live matters: ' + liveMatters.length + '   Action register: ' + actionRows.length
    + ' rows, ' + distinctIds + ' distinct action ids',
  '',
  'Countable open actions (live):        ' + liveOpen.length,
  'Identity conflicts, manual review:    ' + identityConflicts.length,
  'Test-only open actions:               ' + testOpen.length,
  'Closed or completed actions:          ' + doneRecords.length,
  'Historical duplicate rows:            ' + duplicateRows,
  'Attention items shown below:          ' + attentionCount,
  'Open items not shown, no flag set:    ' + notShown,
];
if (accounted !== distinctIds) {
  head.push('RECONCILIATION MISMATCH: ' + accounted + ' accounted for against '
    + distinctIds + ' distinct ids. Treat every figure above as unreliable.');
}
const unreportedNotices = noticesPending.length + noticesFailed.length + noticesExhausted.length;
if (unreportedNotices) {
  head.push('Conflict notices not yet reported to you: ' + unreportedNotices
    + ' (' + noticesPending.length + ' pending, ' + noticesFailed.length + ' failed, '
    + noticesExhausted.length + ' abandoned)');
}
if (identityConflicts.length) {
  head.push('The ' + identityConflicts.length + ' conflicted action id(s) are listed in full below.'
    + ' They are excluded from the countable figure, not discarded.');
}

const footer = [
  '',
  'Sections above are attention-only. An action with no flag is open and needs nothing from you today.',
  'Dates marked UNVERIFIED_ESTIMATE are my estimates, not legal deadlines.',
  'Dates marked NO_BASIS_RECORDED have no recorded source at all.',
  'I do not calculate limitation periods. Confirm any date that matters with a lawyer.',
];

// Budget the message rather than cutting it silently at the end.
let keptBlocks = built.slice();
let droppedSections = 0;
function assemble(list) { return head.concat([''], list).concat(footer).join('\n'); }
function inOrder(list) { return list.slice().sort((a, b) => a.i - b.i).map(b => b.text); }
while (assemble(inOrder(keptBlocks)).length > CEILING) {
  // yield the highest priority number present; never priority 0
  const maxP = Math.max.apply(null, keptBlocks.map(b => b.p));
  if (maxP === 0) break;
  const victim = keptBlocks.map((b, n) => ({ b, n })).filter(x => x.b.p === maxP).pop();
  keptBlocks.splice(victim.n, 1);
  droppedSections++;
}
let kept = inOrder(keptBlocks);
if (droppedSections) {
  kept = kept.concat(['[' + droppedSections + ' further section(s) omitted to fit one message. The full picture is on the sheets.]']);
}

const body = blocks.length
  ? assemble(kept)
  : head.concat(['', 'Nothing needs your attention today.']).concat(footer).join('\n');

return [{ json: {
  reply: body,
  reply_chars: body.length,
  item_count: blocks.length,
  sections_omitted: droppedSections,
  diagnostics: {
    action_rows_read: actionRows.length,
    distinct_action_ids: Object.keys(rowsById).length,
    canonical_records: records.length,
    live_open_actions: liveOpen.length,
    test_open_actions: testOpen.length,
    attention_count: attentionCount,
    not_shown_count: notShown,
    done_actions: doneRecords.length,
    duplicate_rows: duplicateRows,
    accounted_total: accounted,
    reconciles: accounted === distinctIds,
    identity_conflicts: identityConflicts,
    collapsed_duplicates: collapsed,
    live_approvals: liveApprovals.map(a => a.approval_id),
    superseded_unrecorded: supersededUnrecorded,
    approval_state_unknown: approvalStateUnknown,
    multiple_live_approvals: multiLiveApproval,
    test_matter_ids: Object.keys(testMatterIds),
    notices_total: notices.length,
    notices_pending: noticesPending.length,
    notices_failed: noticesFailed.length,
    notices_exhausted: noticesExhausted.length,
    notice_duplicate_keys: noticeDuplicates,
  },
} }];

// Find actions that were sent, whose follow-up date has passed, and that nobody answered.
// This creates a follow-up ACTION only. It never sends anything.
//
// LATCH FIX: this node requires a parseable due_at to raise a chaser, but it used to create
// chasers with due_at set to an empty string. So a chaser that was itself ignored could
// never be chased again -- the follow-up system stopped after exactly one attempt, silently.
// Chasers now carry a real next-review date, and the ladder below makes repeated silence
// visible instead of letting it fade out.
const matters = $('Load Matters (FU)').all().map(i => i.json).filter(r => r && r.matter_id);
const actions = $('Load Actions (FU)').all().map(i => i.json).filter(r => r && r.action_id);
const comms   = $input.all().map(i => i.json).filter(r => r && r.communication_id);
const now = Date.now();
const stamp = new Date().toISOString();
const today = stamp.slice(0, 10);

// A process cadence, not a legal deadline. FOLLOW_UP_SCHEDULE is deliberately a distinct
// basis from UNVERIFIED_ESTIMATE so the digest never presents it as a date with legal weight.
const CHASE_INTERVAL_DAYS = 7;
const MAX_CHASES = 5;

const out = [];
for (const a of actions) {
  if (String(a.status || '').toUpperCase() !== 'SENT') continue;

  const due = Date.parse(String(a.due_at || ''));
  if (Number.isNaN(due) || due > now) continue;

  // A reply on this matter after the send closes the follow-up.
  const sentAt = Date.parse(String(a.updated_at || a.created_at || '')) || 0;
  const replied = comms.some(c =>
    String(c.matter_id) === String(a.matter_id) &&
    String(c.direction || '').toUpperCase() === 'INBOUND' &&
    (Date.parse(String(c.received_at || '')) || 0) >= sentAt);
  if (replied) continue;

  // One open follow-up per parent action at a time.
  const parentKey = String(a.action_id) + '|FU';
  const existing = actions.filter(x =>
    String(x.idempotency_key || '').startsWith(parentKey) &&
    !['COMPLETED','FAILED','SENT'].includes(String(x.status || '').toUpperCase()));
  if (existing.length) continue;

  // Which attempt is this. Counted from every chaser ever raised on this parent, so the
  // count survives chasers that have already been sent.
  const priorChases = actions.filter(x =>
    String(x.idempotency_key || '').startsWith(parentKey)).length;
  const attempt = priorChases + 1;

  const m = matters.filter(x => String(x.matter_id) === String(a.matter_id));
  const matter = m.length ? m[m.length - 1] : {};
  if (['CLOSED','REJECTED'].includes(String(matter.status || '').toUpperCase())) continue;

  // Stop chasing eventually. Silence after five attempts is a decision for the owner,
  // not something to automate indefinitely.
  if (attempt > MAX_CHASES) continue;

  const nextReview = new Date(now + CHASE_INTERVAL_DAYS * 86400000).toISOString();
  const escalating = attempt >= 3;

  out.push({ json: {
    action_id: String(a.action_id) + '-FU' + attempt,
    matter_id: a.matter_id,
    matter_title: String(matter.title || ''),
    parent_action_id: a.action_id,
    action_type: 'FOLLOW_UP',
    description: 'Follow-up attempt ' + attempt + ' of ' + MAX_CHASES + ' on ' + a.action_id
      + ' (' + a.action_type + '), sent to ' + (a.recipient || 'the recipient')
      + ' and unanswered since ' + String(a.updated_at || '').slice(0, 10) + '. '
      + (escalating
          ? 'I have now chased this recipient ' + (attempt - 1) + ' time(s) without a reply. '
            + 'Prepare a firmer but still factual chaser, and note in it that earlier correspondence went unanswered. '
          : 'Prepare a short, polite chaser. ')
      + 'Do not add new legal claims.',
    status: 'READY',
    priority: escalating ? 'HIGH' : 'MEDIUM',
    recipient: String(a.recipient || ''),
    channel: 'GMAIL',
    requires_approval: 'TRUE',
    // The latch fix. Without a parseable date here this chaser could never itself be chased.
    due_at: nextReview,
    deadline_basis: 'FOLLOW_UP_SCHEDULE',
    attempt: attempt,
    idempotency_key: parentKey + '|' + today,
    created_at: stamp,
    updated_at: stamp,
  }});
}
return out;

// The payload workflow 4 expects on its Execute Workflow Trigger.
const rows = $('Find Due Follow-ups').all().map(i => i.json);
return rows.map(r => ({ json: {
  route: 'FOLLOW_UP_REQUEST',
  route_group: 'DRAFT',
  chat_id: '<REDACTED_CHATID_4>',
  owner_chat_id: '<REDACTED_CHATID_4>',
  matter_ref: r.matter_id,
  target_action_id: r.action_id,
  draft_ref: '',
  payload_text: r.description,
  text: r.description,
  session_matter_id: r.matter_id,
}}));

// Extract DeepSeek response and wrap in {output: ...} to match Validate Reply JSON contract.
// Fail-closed: any parse error returns {output: null}.
// Validate Reply JSON handles null: sets cls='UNKNOWN', notes='CLASSIFIER_FAILED'.
const response = $input.first().json;
let parsed = null;
try {
  const content = response.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = null;
}
return [{ json: { output: parsed } }];
